// Builds the in-browser mock backend from the static demo (index.html at the repository root).
//
//   src/engine/legacy.gen.js   the demo's script as a string, minus its DOM boot; src/engine/engine.ts runs it
//                              behind inert DOM shims and the React app talks to it only through src/api/*
//   src/styles/legacy.gen.css  the demo's stylesheet, so React pages keep the same look and class names
//   public/assets/products/    the product photos
//
// Runs before `npm run dev` and `npm run build`. Generated files are not committed: index.html stays the single
// source of truth until the Python backend (docs/PLAN_FULLSTACK_POC.md, phases 1-4) replaces the engine.
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const web = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const candidates = [process.env.LEGACY_HTML, resolve(web, '../../index.html'), '/legacy/index.html'].filter(Boolean);
const htmlPath = candidates.find((p) => existsSync(p));
if (!htmlPath) throw new Error('index.html not found; looked in ' + candidates.join(', '));

const genJs = join(web, 'src/engine/legacy.gen.js');
const genCss = join(web, 'src/styles/legacy.gen.css');
if (existsSync(genJs) && existsSync(genCss) && statSync(genJs).mtimeMs >= statSync(htmlPath).mtimeMs && !process.argv.includes('--force')) {
  console.log('[engine] up to date');
  process.exit(0);
}

const html = readFileSync(htmlPath, 'utf8');
const script = /<script>([\s\S]*)<\/script>\s*<\/body>/.exec(html)?.[1];
const style = /<style>([\s\S]*?)<\/style>/.exec(html)?.[1];
if (!script || !style) throw new Error('could not find the <script> or <style> block in ' + htmlPath);

// The demo boots itself into the page; the React app boots the engine instead (src/engine/engine.ts).
const BOOT = [
  /^afBoot\(\);S\.acct=sessionLoad\(\);.*$/m, // sign-in, shell and first route
  /^setInterval\(\(\)=>\{try\{smTick\(\)\}.*$/m, // live-activity ticker; the engine exposes smTick instead
];
let src = script;
for (const re of BOOT) {
  if (!re.test(src)) throw new Error('boot line not found: ' + re + ' (did index.html change?)');
  src = src.replace(re, '');
}

mkdirSync(dirname(genJs), { recursive: true });
mkdirSync(dirname(genCss), { recursive: true });
writeFileSync(genJs, '// GENERATED by scripts/extract-engine.mjs from index.html. Do not edit.\nexport default ' + JSON.stringify(src) + ';\n');
writeFileSync(genCss, '/* GENERATED by scripts/extract-engine.mjs from index.html. Do not edit. */\n' + style);

const photos = resolve(dirname(htmlPath), 'assets/products');
if (existsSync(photos)) {
  const out = join(web, 'public/assets/products');
  mkdirSync(out, { recursive: true });
  for (const f of readdirSync(photos)) if (/\.(webp|png|jpe?g)$/i.test(f)) copyFileSync(join(photos, f), join(out, f));
}
console.log(`[engine] ${htmlPath} -> legacy.gen.js (${(src.length / 1024) | 0} KB), legacy.gen.css (${(style.length / 1024) | 0} KB)`);
